-- ENKAI LODGEFLOW — PHASE 3
-- Multi-tenant Lodge Management ERP foundation.
--
-- Design rules:
--  * Every tenant-owned row carries tenant_id (directly, or through a strict
--    parent FK). Branch-owned rows also carry branch_id.
--  * IDs are TEXT generated by the application so existing Phase 1/2
--    identifiers remain valid.
--  * Nothing is dropped or truncated. Existing room rows keep working; they
--    become tenant-scoped once a tenant is assigned.
--  * Migrations are applied once, in filename order, by scripts/migrate.ts.

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- ---------------------------------------------------------------------------
-- PLATFORM
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS tenants (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  slug          TEXT NOT NULL,
  legal_name    TEXT,
  email         TEXT,
  phone         TEXT,
  country       TEXT NOT NULL DEFAULT 'Tanzania',
  currency      CHAR(3) NOT NULL DEFAULT 'TZS',
  timezone      TEXT NOT NULL DEFAULT 'Africa/Dar_es_Salaam',
  status        TEXT NOT NULL DEFAULT 'PENDING',
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT tenants_name_not_blank CHECK (btrim(name) <> ''),
  CONSTRAINT tenants_status_valid CHECK (status IN ('PENDING', 'ACTIVE', 'SUSPENDED', 'DEACTIVATED'))
);
CREATE UNIQUE INDEX IF NOT EXISTS tenants_slug_unique ON tenants (lower(btrim(slug)));

CREATE TABLE IF NOT EXISTS tenant_features (
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  feature_key TEXT NOT NULL,
  enabled     BOOLEAN NOT NULL DEFAULT true,
  PRIMARY KEY (tenant_id, feature_key)
);

-- ---------------------------------------------------------------------------
-- BRANCHES / BUILDINGS / FLOORS
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS branches (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  code        TEXT,
  address     TEXT,
  city        TEXT,
  phone       TEXT,
  is_default  BOOLEAN NOT NULL DEFAULT false,
  status      TEXT NOT NULL DEFAULT 'ACTIVE',
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT branches_name_not_blank CHECK (btrim(name) <> ''),
  CONSTRAINT branches_status_valid CHECK (status IN ('ACTIVE', 'INACTIVE'))
);
CREATE UNIQUE INDEX IF NOT EXISTS branches_tenant_name_unique ON branches (tenant_id, lower(btrim(name)));
CREATE INDEX IF NOT EXISTS branches_tenant_idx ON branches (tenant_id);

CREATE TABLE IF NOT EXISTS buildings (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT buildings_name_not_blank CHECK (btrim(name) <> '')
);
CREATE INDEX IF NOT EXISTS buildings_branch_idx ON buildings (branch_id);

CREATE TABLE IF NOT EXISTS floors (
  id           TEXT PRIMARY KEY,
  tenant_id    TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id    TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  building_id  TEXT REFERENCES buildings (id) ON DELETE SET NULL,
  name         TEXT NOT NULL,
  level        INTEGER,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT floors_name_not_blank CHECK (btrim(name) <> '')
);
CREATE INDEX IF NOT EXISTS floors_branch_idx ON floors (branch_id);

-- ---------------------------------------------------------------------------
-- USERS, ROLES, PERMISSIONS, SESSIONS
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS permissions (
  key         TEXT PRIMARY KEY,
  description TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS roles (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT REFERENCES tenants (id) ON DELETE CASCADE,
  key         TEXT NOT NULL,
  name        TEXT NOT NULL,
  description TEXT,
  is_system   BOOLEAN NOT NULL DEFAULT false,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS roles_scope_key_unique
  ON roles (COALESCE(tenant_id, 'PLATFORM'), key);

CREATE TABLE IF NOT EXISTS role_permissions (
  role_id        TEXT NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
  permission_key TEXT NOT NULL REFERENCES permissions (key) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_key)
);

CREATE TABLE IF NOT EXISTS users (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT REFERENCES tenants (id) ON DELETE CASCADE,
  email         TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  display_name  TEXT NOT NULL,
  phone         TEXT,
  status        TEXT NOT NULL DEFAULT 'ACTIVE',
  last_login_at TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT users_email_not_blank CHECK (btrim(email) <> ''),
  CONSTRAINT users_status_valid CHECK (status IN ('ACTIVE', 'SUSPENDED', 'DEACTIVATED'))
);
CREATE UNIQUE INDEX IF NOT EXISTS users_email_unique ON users (lower(btrim(email)));
CREATE INDEX IF NOT EXISTS users_tenant_idx ON users (tenant_id);

CREATE TABLE IF NOT EXISTS user_roles (
  user_id   TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role_id   TEXT NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
  branch_id TEXT REFERENCES branches (id) ON DELETE SET NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS user_roles_unique
  ON user_roles (user_id, role_id, COALESCE(branch_id, ''));

CREATE TABLE IF NOT EXISTS sessions (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash   TEXT NOT NULL,
  expires_at   TIMESTAMPTZ NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ip           TEXT,
  user_agent   TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS sessions_token_hash_unique ON sessions (token_hash);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions (user_id);

CREATE TABLE IF NOT EXISTS audit_logs (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT REFERENCES tenants (id) ON DELETE SET NULL,
  branch_id     TEXT REFERENCES branches (id) ON DELETE SET NULL,
  actor_user_id TEXT REFERENCES users (id) ON DELETE SET NULL,
  actor_email   TEXT,
  action        TEXT NOT NULL,
  entity_type   TEXT,
  entity_id     TEXT,
  metadata      JSONB NOT NULL DEFAULT '{}'::jsonb,
  ip            TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS audit_logs_tenant_idx ON audit_logs (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS audit_logs_actor_idx ON audit_logs (actor_user_id, created_at DESC);

-- ---------------------------------------------------------------------------
-- GUESTS
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS guests (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id        TEXT REFERENCES branches (id) ON DELETE SET NULL,
  full_name        TEXT NOT NULL,
  email            TEXT,
  phone            TEXT,
  nationality      TEXT,
  id_type          TEXT,
  id_number        TEXT,
  address          TEXT,
  notes            TEXT,
  preferences      JSONB NOT NULL DEFAULT '{}'::jsonb,
  marketing_consent BOOLEAN NOT NULL DEFAULT false,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  archived_at      TIMESTAMPTZ,
  CONSTRAINT guests_name_not_blank CHECK (btrim(full_name) <> '')
);
CREATE INDEX IF NOT EXISTS guests_tenant_idx ON guests (tenant_id, created_at DESC);
CREATE INDEX IF NOT EXISTS guests_tenant_phone_idx ON guests (tenant_id, phone);

-- ---------------------------------------------------------------------------
-- ROOMS: extend the Gate 2.0 inventory
-- ---------------------------------------------------------------------------

ALTER TABLE room_categories ADD COLUMN IF NOT EXISTS tenant_id TEXT REFERENCES tenants (id) ON DELETE CASCADE;
ALTER TABLE room_categories ADD COLUMN IF NOT EXISTS branch_id TEXT REFERENCES branches (id) ON DELETE SET NULL;

ALTER TABLE rooms ADD COLUMN IF NOT EXISTS tenant_id TEXT REFERENCES tenants (id) ON DELETE CASCADE;
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS branch_id TEXT REFERENCES branches (id) ON DELETE SET NULL;
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS building_id TEXT REFERENCES buildings (id) ON DELETE SET NULL;
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS floor_id TEXT REFERENCES floors (id) ON DELETE SET NULL;
ALTER TABLE rooms ADD COLUMN IF NOT EXISTS room_type TEXT;

ALTER TABLE rooms DROP CONSTRAINT IF EXISTS rooms_status_valid;
ALTER TABLE rooms ADD CONSTRAINT rooms_status_valid CHECK (
  status IN (
    'AVAILABLE', 'OCCUPIED', 'RESERVED', 'DIRTY', 'CLEANING',
    'INSPECTION', 'READY', 'MAINTENANCE', 'OUT_OF_SERVICE'
  )
);

-- Replace the global uniqueness rules with tenant/branch scoped rules.
DROP INDEX IF EXISTS room_categories_name_unique;
DROP INDEX IF EXISTS rooms_room_number_unique;

CREATE UNIQUE INDEX IF NOT EXISTS room_categories_tenant_name_unique
  ON room_categories (tenant_id, lower(btrim(name)))
  WHERE tenant_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS rooms_tenant_branch_number_unique
  ON rooms (tenant_id, branch_id, lower(btrim(room_number)))
  WHERE archived_at IS NULL AND tenant_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS rooms_tenant_branch_idx ON rooms (tenant_id, branch_id) WHERE archived_at IS NULL;

-- Import runs are tenant-scoped so two businesses can migrate identical
-- Phase 1 payloads without colliding.
ALTER TABLE room_import_runs ADD COLUMN IF NOT EXISTS tenant_id TEXT REFERENCES tenants (id) ON DELETE CASCADE;
DROP INDEX IF EXISTS room_import_runs_payload_hash_unique;
CREATE UNIQUE INDEX IF NOT EXISTS room_import_runs_tenant_payload_unique
  ON room_import_runs (tenant_id, payload_hash);

-- ---------------------------------------------------------------------------
-- RESERVATIONS / STAYS
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS reservations (
  id                  TEXT PRIMARY KEY,
  tenant_id           TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id           TEXT NOT NULL REFERENCES branches (id) ON DELETE RESTRICT,
  guest_id            TEXT NOT NULL REFERENCES guests (id) ON DELETE RESTRICT,
  room_id             TEXT NOT NULL REFERENCES rooms (id) ON DELETE RESTRICT,
  status              TEXT NOT NULL DEFAULT 'PENDING',
  check_in_date       DATE NOT NULL,
  check_out_date      DATE NOT NULL,
  adults              INTEGER NOT NULL DEFAULT 1,
  children            INTEGER NOT NULL DEFAULT 0,
  source              TEXT NOT NULL DEFAULT 'DIRECT',
  rate_amount         NUMERIC(12, 2),
  rate_plan           TEXT,
  notes               TEXT,
  created_by          TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  cancelled_at        TIMESTAMPTZ,
  cancellation_reason TEXT,
  CHECK (check_out_date > check_in_date),
  CHECK (adults BETWEEN 1 AND 20),
  CHECK (children BETWEEN 0 AND 20),
  CONSTRAINT reservations_status_valid CHECK (
    status IN ('PENDING', 'CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED', 'NO_SHOW')
  )
);

-- Two active reservations for the same room may never overlap.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'reservations_no_overlap'
  ) THEN
    ALTER TABLE reservations
      ADD CONSTRAINT reservations_no_overlap
      EXCLUDE USING gist (
        room_id WITH =,
        daterange(check_in_date, check_out_date, '[)') WITH &&
      )
      WHERE (status IN ('PENDING', 'CONFIRMED', 'CHECKED_IN'));
  END IF;
END
$$;

CREATE INDEX IF NOT EXISTS reservations_tenant_branch_idx
  ON reservations (tenant_id, branch_id, check_in_date DESC);
CREATE INDEX IF NOT EXISTS reservations_guest_idx ON reservations (tenant_id, guest_id);

CREATE TABLE IF NOT EXISTS guest_stays (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id        TEXT NOT NULL REFERENCES branches (id) ON DELETE RESTRICT,
  reservation_id   TEXT REFERENCES reservations (id) ON DELETE SET NULL,
  guest_id         TEXT NOT NULL REFERENCES guests (id) ON DELETE RESTRICT,
  room_id          TEXT NOT NULL REFERENCES rooms (id) ON DELETE RESTRICT,
  status           TEXT NOT NULL DEFAULT 'ACTIVE',
  check_in_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  check_out_at     TIMESTAMPTZ,
  checked_in_by    TEXT REFERENCES users (id) ON DELETE SET NULL,
  checked_out_by   TEXT REFERENCES users (id) ON DELETE SET NULL,
  room_charge      NUMERIC(12, 2),
  notes            TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT guest_stays_status_valid CHECK (status IN ('ACTIVE', 'CLOSED'))
);
CREATE UNIQUE INDEX IF NOT EXISTS guest_stays_one_active_per_room
  ON guest_stays (room_id) WHERE status = 'ACTIVE';
CREATE INDEX IF NOT EXISTS guest_stays_tenant_idx ON guest_stays (tenant_id, branch_id, status);

CREATE TABLE IF NOT EXISTS guest_requests (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  guest_id    TEXT REFERENCES guests (id) ON DELETE SET NULL,
  stay_id     TEXT REFERENCES guest_stays (id) ON DELETE SET NULL,
  category    TEXT NOT NULL DEFAULT 'OTHER',
  description TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'OPEN',
  priority    TEXT NOT NULL DEFAULT 'NORMAL',
  created_by  TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at TIMESTAMPTZ,
  CONSTRAINT guest_requests_status_valid CHECK (status IN ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CANCELLED'))
);
CREATE INDEX IF NOT EXISTS guest_requests_tenant_idx ON guest_requests (tenant_id, status, created_at DESC);

-- ---------------------------------------------------------------------------
-- HOUSEKEEPING / MAINTENANCE
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS housekeeping_tasks (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id        TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  room_id          TEXT NOT NULL REFERENCES rooms (id) ON DELETE RESTRICT,
  stay_id          TEXT REFERENCES guest_stays (id) ON DELETE SET NULL,
  task_type        TEXT NOT NULL DEFAULT 'DEPARTURE',
  status           TEXT NOT NULL DEFAULT 'PENDING',
  priority         TEXT NOT NULL DEFAULT 'NORMAL',
  assigned_to      TEXT REFERENCES users (id) ON DELETE SET NULL,
  notes            TEXT,
  created_by       TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  started_at       TIMESTAMPTZ,
  completed_at     TIMESTAMPTZ,
  inspected_by     TEXT REFERENCES users (id) ON DELETE SET NULL,
  inspection_notes TEXT,
  CONSTRAINT housekeeping_task_type_valid CHECK (task_type IN ('DEPARTURE', 'STAYOVER', 'DEEP_CLEAN', 'INSPECTION', 'MAINTENANCE')),
  CONSTRAINT housekeeping_status_valid CHECK (status IN ('PENDING', 'IN_PROGRESS', 'INSPECTION', 'COMPLETED', 'FAILED')),
  CONSTRAINT housekeeping_priority_valid CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'URGENT'))
);
CREATE INDEX IF NOT EXISTS housekeeping_tenant_idx ON housekeeping_tasks (tenant_id, branch_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS room_inspections (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id     TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  task_id       TEXT REFERENCES housekeeping_tasks (id) ON DELETE SET NULL,
  room_id       TEXT NOT NULL REFERENCES rooms (id) ON DELETE RESTRICT,
  passed        BOOLEAN NOT NULL,
  notes         TEXT,
  inspected_by  TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS room_inspections_tenant_idx ON room_inspections (tenant_id, room_id, created_at DESC);

CREATE TABLE IF NOT EXISTS maintenance_requests (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  room_id     TEXT REFERENCES rooms (id) ON DELETE SET NULL,
  title       TEXT NOT NULL,
  description TEXT,
  status      TEXT NOT NULL DEFAULT 'OPEN',
  priority    TEXT NOT NULL DEFAULT 'NORMAL',
  reported_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  assigned_to TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at TIMESTAMPTZ,
  CONSTRAINT maintenance_status_valid CHECK (status IN ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CANCELLED'))
);
CREATE INDEX IF NOT EXISTS maintenance_tenant_idx ON maintenance_requests (tenant_id, status, created_at DESC);

-- ---------------------------------------------------------------------------
-- FINANCE
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS invoices (
  id             TEXT PRIMARY KEY,
  tenant_id      TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id      TEXT NOT NULL REFERENCES branches (id) ON DELETE RESTRICT,
  guest_id       TEXT REFERENCES guests (id) ON DELETE SET NULL,
  stay_id        TEXT REFERENCES guest_stays (id) ON DELETE SET NULL,
  reservation_id TEXT REFERENCES reservations (id) ON DELETE SET NULL,
  number         TEXT NOT NULL,
  status         TEXT NOT NULL DEFAULT 'DRAFT',
  currency       CHAR(3) NOT NULL DEFAULT 'TZS',
  subtotal       NUMERIC(12, 2) NOT NULL DEFAULT 0,
  tax            NUMERIC(12, 2) NOT NULL DEFAULT 0,
  total          NUMERIC(12, 2) NOT NULL DEFAULT 0,
  amount_paid    NUMERIC(12, 2) NOT NULL DEFAULT 0,
  issued_at      TIMESTAMPTZ,
  due_at         TIMESTAMPTZ,
  notes          TEXT,
  created_by     TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT invoices_status_valid CHECK (status IN ('DRAFT', 'ISSUED', 'PARTIALLY_PAID', 'PAID', 'VOID')),
  CONSTRAINT invoices_amounts_non_negative CHECK (subtotal >= 0 AND tax >= 0 AND total >= 0 AND amount_paid >= 0)
);
CREATE UNIQUE INDEX IF NOT EXISTS invoices_tenant_number_unique ON invoices (tenant_id, number);
CREATE INDEX IF NOT EXISTS invoices_tenant_idx ON invoices (tenant_id, branch_id, created_at DESC);

CREATE TABLE IF NOT EXISTS invoice_items (
  id          TEXT PRIMARY KEY,
  invoice_id  TEXT NOT NULL REFERENCES invoices (id) ON DELETE CASCADE,
  description TEXT NOT NULL,
  quantity    NUMERIC(10, 2) NOT NULL DEFAULT 1,
  unit_price  NUMERIC(12, 2) NOT NULL,
  line_total  NUMERIC(12, 2) NOT NULL,
  kind        TEXT NOT NULL DEFAULT 'ROOM',
  CHECK (quantity > 0),
  CHECK (unit_price >= 0),
  CHECK (line_total >= 0)
);
CREATE INDEX IF NOT EXISTS invoice_items_invoice_idx ON invoice_items (invoice_id);

CREATE TABLE IF NOT EXISTS payments (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE RESTRICT,
  invoice_id  TEXT NOT NULL REFERENCES invoices (id) ON DELETE RESTRICT,
  amount      NUMERIC(12, 2) NOT NULL,
  method      TEXT NOT NULL,
  reference   TEXT,
  received_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  paid_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (amount > 0),
  CONSTRAINT payments_method_valid CHECK (method IN ('CASH', 'CARD', 'MOBILE_MONEY', 'BANK_TRANSFER', 'OTHER'))
);
CREATE INDEX IF NOT EXISTS payments_tenant_idx ON payments (tenant_id, branch_id, paid_at DESC);
CREATE INDEX IF NOT EXISTS payments_invoice_idx ON payments (invoice_id);

CREATE TABLE IF NOT EXISTS expenses (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE RESTRICT,
  category    TEXT NOT NULL,
  description TEXT NOT NULL,
  amount      NUMERIC(12, 2) NOT NULL,
  method      TEXT NOT NULL DEFAULT 'CASH',
  reference   TEXT,
  spent_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  recorded_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (amount > 0),
  CONSTRAINT expenses_method_valid CHECK (method IN ('CASH', 'CARD', 'MOBILE_MONEY', 'BANK_TRANSFER', 'OTHER'))
);
CREATE INDEX IF NOT EXISTS expenses_tenant_idx ON expenses (tenant_id, branch_id, spent_at DESC);

-- ---------------------------------------------------------------------------
-- STAFF OPERATIONS
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS staff_shifts (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  user_id     TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role_label  TEXT,
  starts_at   TIMESTAMPTZ NOT NULL,
  ends_at     TIMESTAMPTZ NOT NULL,
  status      TEXT NOT NULL DEFAULT 'SCHEDULED',
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (ends_at > starts_at),
  CONSTRAINT shifts_status_valid CHECK (status IN ('SCHEDULED', 'ACTIVE', 'COMPLETED', 'CANCELLED'))
);
CREATE INDEX IF NOT EXISTS shifts_tenant_idx ON staff_shifts (tenant_id, branch_id, starts_at);

CREATE TABLE IF NOT EXISTS staff_attendance (
  id           TEXT PRIMARY KEY,
  tenant_id    TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id    TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  shift_id     TEXT REFERENCES staff_shifts (id) ON DELETE SET NULL,
  clock_in_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  clock_out_at TIMESTAMPTZ,
  status       TEXT NOT NULL DEFAULT 'PRESENT',
  CONSTRAINT attendance_status_valid CHECK (status IN ('PRESENT', 'LATE', 'ABSENT', 'LEFT_EARLY'))
);
CREATE INDEX IF NOT EXISTS attendance_tenant_idx ON staff_attendance (tenant_id, branch_id, clock_in_at DESC);

-- ---------------------------------------------------------------------------
-- CCTV INTELLIGENCE
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS cameras (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  room_id     TEXT REFERENCES rooms (id) ON DELETE SET NULL,
  name        TEXT NOT NULL,
  location    TEXT,
  rtsp_url    TEXT,
  status      TEXT NOT NULL DEFAULT 'UNCONFIGURED',
  mode        TEXT NOT NULL DEFAULT 'UPLOAD_PROTOTYPE',
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT cameras_status_valid CHECK (status IN ('ONLINE', 'OFFLINE', 'UNCONFIGURED', 'ERROR')),
  CONSTRAINT cameras_mode_valid CHECK (mode IN ('UPLOAD_PROTOTYPE', 'RTSP'))
);
CREATE INDEX IF NOT EXISTS cameras_tenant_idx ON cameras (tenant_id, branch_id);

CREATE TABLE IF NOT EXISTS video_recordings (
  id               TEXT PRIMARY KEY,
  tenant_id        TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id        TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  camera_id        TEXT REFERENCES cameras (id) ON DELETE SET NULL,
  room_id          TEXT REFERENCES rooms (id) ON DELETE SET NULL,
  filename         TEXT NOT NULL,
  mime_type        TEXT,
  size_bytes       BIGINT,
  storage_path     TEXT,
  duration_seconds NUMERIC(10, 2),
  recorded_at      TIMESTAMPTZ,
  uploaded_by      TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS recordings_tenant_idx ON video_recordings (tenant_id, created_at DESC);

CREATE TABLE IF NOT EXISTS video_analysis_jobs (
  id            TEXT PRIMARY KEY,
  tenant_id     TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id     TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  camera_id     TEXT REFERENCES cameras (id) ON DELETE SET NULL,
  room_id       TEXT REFERENCES rooms (id) ON DELETE SET NULL,
  recording_id  TEXT REFERENCES video_recordings (id) ON DELETE SET NULL,
  status        TEXT NOT NULL DEFAULT 'QUEUED',
  phase         TEXT,
  model         TEXT,
  requested_by  TEXT REFERENCES users (id) ON DELETE SET NULL,
  error_code    TEXT,
  error_message TEXT,
  started_at    TIMESTAMPTZ,
  completed_at  TIMESTAMPTZ,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT analysis_job_status_valid CHECK (
    status IN ('QUEUED', 'UPLOADING', 'PROCESSING', 'COMPLETED', 'FAILED', 'NEEDS_REVIEW')
  )
);
CREATE INDEX IF NOT EXISTS analysis_jobs_tenant_idx ON video_analysis_jobs (tenant_id, created_at DESC);

CREATE TABLE IF NOT EXISTS gemini_analyses (
  id          TEXT PRIMARY KEY,
  job_id      TEXT NOT NULL REFERENCES video_analysis_jobs (id) ON DELETE CASCADE,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  model       TEXT,
  raw_output  JSONB NOT NULL DEFAULT '{}'::jsonb,
  valid       BOOLEAN NOT NULL DEFAULT false,
  confidence  NUMERIC(5, 2),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS occupancy_events (
  id                  TEXT PRIMARY KEY,
  job_id              TEXT NOT NULL REFERENCES video_analysis_jobs (id) ON DELETE CASCADE,
  tenant_id           TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id           TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  room_id             TEXT REFERENCES rooms (id) ON DELETE SET NULL,
  event_type          TEXT NOT NULL,
  person_id           TEXT,
  video_timestamp_sec NUMERIC(10, 2),
  confidence          NUMERIC(5, 2),
  verified            BOOLEAN NOT NULL DEFAULT false,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT occupancy_event_type_valid CHECK (
    event_type IN ('ENTRY', 'EXIT', 'RE_ENTRY', 'CORRIDOR_PASS', 'UNKNOWN')
  )
);
CREATE INDEX IF NOT EXISTS occupancy_events_job_idx ON occupancy_events (job_id, video_timestamp_sec);
CREATE INDEX IF NOT EXISTS occupancy_events_tenant_idx ON occupancy_events (tenant_id, created_at DESC);

CREATE TABLE IF NOT EXISTS occupancy_states (
  id                     TEXT PRIMARY KEY,
  tenant_id              TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id              TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  room_id                TEXT NOT NULL REFERENCES rooms (id) ON DELETE RESTRICT,
  job_id                 TEXT REFERENCES video_analysis_jobs (id) ON DELETE SET NULL,
  computed_count         INTEGER NOT NULL,
  registered_guest_count INTEGER,
  confidence             NUMERIC(5, 2),
  derived_lifecycle_state TEXT,
  requires_review        BOOLEAN NOT NULL DEFAULT true,
  created_at             TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS occupancy_states_room_idx ON occupancy_states (tenant_id, room_id, created_at DESC);

CREATE TABLE IF NOT EXISTS doorway_rois (
  id          TEXT PRIMARY KEY,
  tenant_id   TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id   TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  camera_id   TEXT REFERENCES cameras (id) ON DELETE CASCADE,
  room_id     TEXT REFERENCES rooms (id) ON DELETE SET NULL,
  config      JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS cctv_alerts (
  id             TEXT PRIMARY KEY,
  tenant_id      TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  branch_id      TEXT NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
  camera_id      TEXT REFERENCES cameras (id) ON DELETE SET NULL,
  room_id        TEXT REFERENCES rooms (id) ON DELETE SET NULL,
  type           TEXT NOT NULL,
  severity       TEXT NOT NULL DEFAULT 'INFO',
  message        TEXT NOT NULL,
  status         TEXT NOT NULL DEFAULT 'OPEN',
  acknowledged_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  acknowledged_at TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT cctv_alert_severity_valid CHECK (severity IN ('INFO', 'WARNING', 'CRITICAL')),
  CONSTRAINT cctv_alert_status_valid CHECK (status IN ('OPEN', 'ACKNOWLEDGED', 'DISMISSED'))
);
CREATE INDEX IF NOT EXISTS cctv_alerts_tenant_idx ON cctv_alerts (tenant_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS accuracy_validations (
  id         TEXT PRIMARY KEY,
  tenant_id  TEXT NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
  job_id     TEXT REFERENCES video_analysis_jobs (id) ON DELETE SET NULL,
  expected   JSONB NOT NULL DEFAULT '{}'::jsonb,
  actual     JSONB NOT NULL DEFAULT '{}'::jsonb,
  passed     BOOLEAN NOT NULL,
  notes      TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

